.lenz-law-demo {
  font-family: 'Segoe UI', sans-serif;
  max-width: 600px;
  margin: 0 auto;
  padding: 20px;
  background: linear-gradient(135deg, #667eea 0%, #764ba2 100%);
  border-radius: 16px;
  color: white;
}
.instruction {
  text-align: center;
  font-size: 18px;
  margin-bottom: 20px;
  padding: 10px;
  background: rgba(255,255,255,0.2);
  border-radius: 8px;
}
.scene {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 80px;
  height: 200px;
  background: rgba(255,255,255,0.1);
  border-radius: 12px;
  position: relative;
  overflow: hidden;
}
.magnet {
  width: 60px;
  height: 120px;
  background: linear-gradient(90deg, #e74c3c 30%, #c0392b 100%);
  border-radius: 8px;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  cursor: grab;
  user-select: none;
  box-shadow: 0 4px 15px rgba(0,0,0,0.3);
  position: relative;
  transition: transform 0.1s;
}
.magnet:hover {
  transform: scale(1.05);
}
.magnet-n, .magnet-s {
  font-size: 24px;
  font-weight: bold;
  color: white;
  text-shadow: 1px 1px 2px rgba(0,0,0,0.3);
}
.magnet-n {
  background: #e74c3c;
}
.magnet-s {
  background: #2c3e50;
  margin-top: 10px;
}
.coil-container {
  position: relative;
}
.coil-svg {
  width: 120px;
  height: 160px;
}
.current-indicator {
  position: absolute;
  bottom: -30px;
  left: 50%;
  transform: translateX(-50%);
  display: flex;
  flex-direction: column;
  align-items: center;
  opacity: 0;
  transition: opacity 0.3s;
}
.current-indicator.active {
  opacity: 1;
}
.current-arrow {
  width: 0;
  height: 0;
  border-left: 10px solid transparent;
  border-right: 10px solid transparent;
  border-bottom: 20px solid #f1c40f;
  transition: transform 0.3s;
}
.current-arrow.up {
  transform: rotate(180deg);
}
.current-text {
  font-size: 14px;
  margin-top: 5px;
}
.info-panel {
  margin-top: 20px;
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 10px;
}
.info-item {
  background: rgba(255,255,255,0.2);
  padding: 12px;
  border-radius: 8px;
  text-align: center;
}
.info-label {
  display: block;
  font-size: 12px;
  opacity: 0.8;
  margin-bottom: 4px;
}
.info-value {
  font-size: 16px;
  font-weight: bold;
}
.reset-btn {
  display: block;
  margin: 15px auto 0;
  padding: 10px 30px;
  background: rgba(255,255,255,0.3);
  border: none;
  border-radius: 8px;
  color: white;
  font-size: 16px;
  cursor: pointer;
  transition: background 0.3s;
}
.reset-btn:hover {
  background: rgba(255,255,255,0.5);
}

