arguments.js:
const selfMode = document.getElementById('selfMode');
const mutualMode = document.getElementById('mutualMode');
const selfCircuit = document.getElementById('selfCircuit');
const mutualCircuit = document.getElementById('mutualCircuit');
const switchBtn = document.getElementById('switchBtn');
const disconnectBtn = document.getElementById('disconnectBtn');
const varyBtn = document.getElementById('varyBtn');
const obsContent = document.getElementById('obsContent');
const principleText = document.getElementById('principleText');
const bulb = document.getElementById('bulb');
const bulbGlow = document.getElementById('bulbGlow');

let isSelfMode = true;
let currentState = 'off';

// 模式切换
selfMode.addEventListener('click', () => {
  isSelfMode = true;
  selfMode.classList.add('active');
  mutualMode.classList.remove('active');
  selfCircuit.classList.remove('hidden');
  mutualCircuit.classList.add('hidden');
  principleText.textContent = '自感电动势总是阻碍电流的变化。当开关闭合时，线圈会产生自感电动势阻碍电流增大；当开关断开时，自感电动势会维持电流继续流动。';
  reset();
});

mutualMode.addEventListener('click', () => {
  isSelfMode = false;
  mutualMode.classList.add('active');
  selfMode.classList.remove('active');
  selfCircuit.classList.add('hidden');
  mutualCircuit.classList.remove('hidden');
  principleText.textContent = '互感现象：当一个线圈电流变化时，其周围的磁场也会变化，如果另一个线圈在这个变化的磁场中，就会产生感应电动势。这就是变压器的原理。';
  reset();
});

// 闭合开关
switchBtn.addEventListener('click', () => {
  if (!isSelfMode) {
    obsContent.textContent = '原线圈通电 → 产生磁场 → 副线圈磁通量变化 → 副线圈产生感应电动势！';
    window.HeurisStage.emit('experiment-result', {
      type: 'mutual-induction',
      action: 'switch-on',
      result: '互感现象：原线圈电流产生磁场，副线圈感应出电动势'
    });
    return;
  }

  currentState = 'on';
  bulb.style.fill = '#f1c40f';
  bulbGlow.style.opacity = '0.8';
  obsContent.innerHTML = '<span style="color:#f1c40f">⚡ 开关闭合，灯泡正常发光</span><br>由于线圈的自感作用，电流是逐渐增大的（不是瞬间达到最大）。';

  window.HeurisStage.emit('experiment-result', {
    type: 'self-induction',
    action: 'switch-on',
    result: '灯泡正常发光，自感电动势阻碍电流增大'
  });
});

// 断开开关
disconnectBtn.addEventListener('click', () => {
  if (!isSelfMode) {
    obsContent.textContent = '断开原线圈电流 → 磁场迅速消失 → 副线圈感应出反向电动势！';
    window.HeurisStage.emit('experiment-result', {
      type: 'mutual-induction',
      action: 'switch-off',
      result: '互感现象：原线圈电流减小，副线圈感应出电动势'
    });
    return;
  }

  currentState = 'off';
  bulb.style.fill = '#f1c40f';
  bulbGlow.style.opacity = '1';

  setTimeout(() => {
    bulb.style.fill = '#666';
    bulbGlow.style.opacity = '0.3';
  }, 100);

  obsContent.innerHTML = '<span style="color:#e74c3c">💡 开关断开，灯泡<b>闪亮一下</b>才熄灭！</span><br>这是因为线圈产生的自感电动势维持了电流，使灯泡继续亮一会儿。';

  window.HeurisStage.emit('experiment-result', {
    type: 'self-induction',
    action: 'switch-off',
    result: '灯泡闪亮：自感电动势维持电流'
  });
});

// 改变电流
varyBtn.addEventListener('click', () => {
  if (!isSelfMode) {
    obsContent.textContent = '不断改变原线圈电流大小 → 副线圈感应出变化的电动势！电流变化越快，感应电动势越大。';
    window.HeurisStage.emit('experiment-result', {
      type: 'mutual-induction',
      action: 'vary-current',
      result: '电流变化率越大，互感电动势越大'
    });
    return;
  }

  obsContent.innerHTML = '<span style="color:#9b59b6">🔄 电流变化中...</span><br>电流增大 → 自感电动势反向阻碍<br>电流减小 → 自感电动势同向维持<br><b>关键：E = L × (ΔI/Δt)</b>';

  window.HeurisStage.emit('experiment-result', {
    type: 'self-induction',
    action: 'vary-current',
    result: '自感电动势与电流变化率成正比'
  });
});

function reset() {
  currentState = 'off';
  bulb.style.fill = '#666';
  bulbGlow.style.opacity = '0.3';
  obsContent.textContent = '点击按钮进行实验，观察现象...';
}

