const questions = [
  {
    question: "磁通量的公式是？<br><strong>（提示：磁感应强度B，面积S，夹角θ）</strong>",
    answer: "B×S×cosθ",
    acceptedAnswers: ["B×S×cosθ", "B*S*cosθ", "BScosθ", "B S cosθ"],
    hint: "口诀：面积乘磁场，再乘角度余弦"
  },
  {
    question: "导体棒切割磁感线，感应电动势E = ?<br><strong>（B=0.3T, L=0.8m, v=15m/s 时，E=？）</strong>",
    answer: "3.6",
    acceptedAnswers: ["3.6", "3.6V", "3.6 V", "0.3×0.8×15"],
    hint: "口诀：长导线切磁场，速度越快越强"
  },
  {
    question: "闭合电路的电流 I = ?<br><strong>（已知E=3.6V，R=5Ω）</strong>",
    answer: "0.72",
    acceptedAnswers: ["0.72", "0.72A", "0.72 A", "3.6/5"],
    hint: "欧姆定律：I = E/R"
  },
  {
    question: "自感电动势 E = ?<br><strong>（L=0.5H，ΔI=2A，Δt=0.2s）</strong>",
    answer: "5",
    acceptedAnswers: ["5", "5V", "5 V", "0.5×10"],
    hint: "自感系数乘电流变化率"
  },
  {
    question: "变压器电压比公式<br><strong>（原线圈N₁=2200，U₁=220V；副线圈N₂=110）</strong>",
    answer: "11",
    acceptedAnswers: ["11", "11V", "11 V"],
    hint: "口诀：匝数比等于电压比"
  }
];

let currentQuestion = 0;
let score = 0;
let answered = false;

const quizContainer = document.getElementById('quizContainer');
const quizResult = document.getElementById('quizResult');
const scoreEl = document.getElementById('score');
const finalScoreEl = document.getElementById('finalScore');
const resultMessage = document.getElementById('resultMessage');
const restartBtn = document.getElementById('restartBtn');

function renderQuestion() {
  const q = questions[currentQuestion];
  quizContainer.innerHTML = `
    <div class="question">
      <strong>第 ${currentQuestion + 1} / ${questions.length} 题</strong><br><br>
      ${q.question}
    </div>
    <div class="hint">💡 ${q.hint}</div>
    <input type="text" class="formula-input" id="answerInput" placeholder="输入答案..." autocomplete="off">
    <button class="submit-btn" id="submitBtn">提交答案</button>
    <div class="feedback hidden" id="feedback"></div>
  `;

  const input = document.getElementById('answerInput');
  const submitBtn = document.getElementById('submitBtn');

  submitBtn.addEventListener('click', checkAnswer);
  input.addEventListener('keypress', (e) => {
    if (e.key === 'Enter') checkAnswer();
  });

  setTimeout(() => input.focus(), 100);
}

function checkAnswer() {
  if (answered) return;
  answered = true;

  const input = document.getElementById('answerInput');
  const feedback = document.getElementById('feedback');
  const userAnswer = input.value.trim().replace(/\s+/g, '');

  const isCorrect = questions[currentQuestion].acceptedAnswers.some(
    ans => ans.replace(/\s+/g, '') === userAnswer || userAnswer.includes(ans.replace(/\s+/g, ''))
  );

  if (isCorrect) {
    score++;
    scoreEl.textContent = score;
    feedback.className = 'feedback correct';
    feedback.innerHTML = '✅ 回答正确！太棒了！';
    window.HeurisStage.emit('quiz-answer', {
      question: currentQuestion + 1,
      userAnswer: input.value,
      correct: true,
      score: score
    });
  } else {
    feedback.className = 'feedback wrong';
    feedback.innerHTML = `❌ 正确答案是：<strong>${questions[currentQuestion].answer}</strong>`;
    window.HeurisStage.emit('quiz-answer', {
      question: currentQuestion + 1,
      userAnswer: input.value,
      correct: false,
      correctAnswer: questions[currentQuestion].answer,
      score: score
    });
  }

  feedback.classList.remove('hidden');

  setTimeout(() => {
    currentQuestion++;
    answered = false;
    if (currentQuestion < questions.length) {
      renderQuestion();
    } else {
      showResult();
    }
  }, 1500);
}

function showResult() {
  quizContainer.classList.add('hidden');
  quizResult.classList.remove('hidden');
  finalScoreEl.textContent = score;

  if (score === 5) {
    resultMessage.textContent = '🏆 完美！所有公式都记住了！';
  } else if (score >= 3) {
    resultMessage.textContent = '👍 不错！再练习一下不太熟悉的公式！';
  } else {
    resultMessage.textContent = '📚 加油！建议再复习一下公式口诀！';
  }

  window.HeurisStage.emit('quiz-complete', {
    totalQuestions: 5,
    score: score,
    percentage: score / 5 * 100
  });
}

restartBtn.addEventListener('click', () => {
  currentQuestion = 0;
  score = 0;
  scoreEl.textContent = '0';
  quizContainer.classList.remove('hidden');
  quizResult.classList.add('hidden');
  renderQuestion();
});

renderQuestion();

