const magnet = document.getElementById('magnet');
const resetBtn = document.getElementById('resetBtn');
const positionValue = document.getElementById('position-value');
const fluxChange = document.getElementById('flux-change');
const currentDirection = document.getElementById('current-direction');
const currentIndicator = document.querySelector('.current-indicator');
const currentArrow = document.querySelector('.current-arrow');

let isDragging = false;
let startX = 0;
let magnetX = 300;

function updateDisplay() {
  const relativePos = magnetX - 260; // 相对于线圈中心的位置

  positionValue.textContent = relativePos + ' cm';

  // 判断磁通量变化和电流方向
  if (Math.abs(relativePos) < 10) {
    fluxChange.textContent = '— (最大)';
    currentDirection.textContent = '无变化';
    currentIndicator.classList.remove('active');
  } else if (relativePos > 0) {
    fluxChange.textContent = '↑ 远离中';
    fluxChange.style.color = '#f1c40f';
    currentDirection.textContent = '↓ 顺时针';
    currentDirection.style.color = '#e74c3c';
    currentIndicator.classList.add('active');
    currentArrow.classList.remove('up');
  } else {
    fluxChange.textContent = '↑ 靠近中';
    fluxChange.style.color = '#2ecc71';
    currentDirection.textContent = '↑ 逆时针';
    currentDirection.style.color = '#2ecc71';
    currentIndicator.classList.add('active');
    currentArrow.classList.add('up');
  }

  magnet.style.transform = `translateX(${magnetX - 330}px)`;

  // 发射事件
  window.HeurisStage.emit('lenz-demo', {
    magnetPosition: relativePos,
    fluxChange: fluxChange.textContent,
    currentDirection: currentDirection.textContent,
    timestamp: Date.now()
  });
}

magnet.addEventListener('mousedown', (e) => {
  isDragging = true;
  startX = e.clientX - magnetX;
  magnet.style.cursor = 'grabbing';
});

document.addEventListener('mousemove', (e) => {
  if (!isDragging) return;
  magnetX = Math.max(100, Math.min(500, e.clientX - startX));
  updateDisplay();
});

document.addEventListener('mouseup', () => {
  isDragging = false;
  magnet.style.cursor = 'grab';
});

resetBtn.addEventListener('click', () => {
  magnetX = 300;
  updateDisplay();
});

// 初始化
updateDisplay();

