const questions = [
  {
    type: 'choice',
    question: '一个线圈水平放置在磁场中，已知 B = 0.5T，S = 0.02m²，磁场方向垂直穿过线圈。穿过线圈的磁通量 Φ 是多少？',
    options: ['0.01 Wb', '1 Wb', '0.1 Wb', '10 Wb'],
    correct: 0,
    explanation: 'Φ = B × S × cosθ = 0.5 × 0.02 × 1 = 0.01 Wb'
  },
  {
    type: 'calc',
    question: '导体棒长度 L = 0.5m，磁感应强度 B = 0.4T，速度 v = 10m/s。求感应电动势 E = ?（单位：V）',
    answer: '2',
    acceptedAnswers: ['2', '2V', '2 V'],
    explanation: 'E = B × L × v = 0.4 × 0.5 × 10 = 2V'
  },
  {
    type: 'choice',
    question: '当条形磁铁的 N 极迅速靠近线圈时，线圈中的感应电流方向是？',
    options: ['顺时针', '逆时针', '先顺时针后逆时针', '无感应电流'],
    correct: 1,
    explanation: 'N极靠近→磁通量增加→感应电流产生反向磁场阻碍增加→俯视图逆时针'
  },
  {
    type: 'calc',
    question: '线圈的自感系数 L = 0.5H，电流在 0.2s 内从 2A 减小到 0A。自感电动势 E = ?（单位：V）',
    answer: '5',
    acceptedAnswers: ['5', '5V', '5 V'],
    explanation: 'E = L × ΔI/Δt = 0.5 × (2/0.2) = 0.5 × 10 = 5V'
  },
  {
    type: 'choice',
    question: '理想变压器原线圈 2200 匝，副线圈 110 匝，原线圈接 220V 电压。副线圈输出电压是？',
    options: ['220V', '110V', '22V', '11V'],
    correct: 3,
    explanation: 'U₁/U₂ = N₁/N₂ → 220/U₂ = 2200/110 → U₂ = 11V'
  }
];

let currentQuestion = 0;
let userAnswers = new Array(questions.length).fill(null);
let showingResult = false;

const questionArea = document.getElementById('questionArea');
const resultArea = document.getElementById('resultArea');
const resultIcon = document.getElementById('resultIcon');
const resultText = document.getElementById('resultText');
const resultExplanation = document.getElementById('resultExplanation');
const prevBtn = document.getElementById('prevBtn');
const nextBtn = document.getElementById('nextBtn');
const submitQuiz = document.getElementById('submitQuiz');
const currentQEl = document.getElementById('currentQ');
const totalQEl = document.getElementById('totalQ');

function renderQuestion() {
  showingResult = false;
  const q = questions[currentQuestion];
  currentQEl.textContent = currentQuestion + 1;
  totalQEl.textContent = questions.length;

  resultArea.classList.add('hidden');
  questionArea.classList.remove('hidden');

  let html = `<div class="question-num">第 ${currentQuestion + 1} 题</div>`;
  html += `<div class="question-text">${q.question}</div>`;

  if (q.type === 'choice') {
    html += '<div class="options">';
    q.options.forEach((opt, i) => {
      html += `<div class="option" data-index="${i}">${opt}</div>`;
    });
    html += '</div>';
  } else if (q.type === 'calc') {
    html += '<div class="input-area"><input type="text" class="calc-input" id="calcAnswer" placeholder="输入数值..."></div>';
  }

  questionArea.innerHTML = html;

  // 更新按钮状态
  prevBtn.disabled = currentQuestion === 0;
  if (currentQuestion === questions.length - 1) {
    nextBtn.classList.add('hidden');
    submitQuiz.classList.remove('hidden');
  } else {
    nextBtn.classList.remove('hidden');
    submitQuiz.classList.add('hidden');
  }

  // 绑定选项事件
  if (q.type === 'choice') {
    document.querySelectorAll('.option').forEach(opt => {
      opt.addEventListener('click', () => selectOption(parseInt(opt.dataset.index)));
    });
  }
}

function selectOption(index) {
  userAnswers[currentQuestion] = { type: 'choice', selected: index };
  showResult();
}

function showResult() {
  showingResult = true;
  const q = questions[currentQuestion];
  const answer = userAnswers[currentQuestion];

  questionArea.classList.add('hidden');
  resultArea.classList.remove('hidden');

  let isCorrect = false;

  if (q.type === 'choice') {
    const selected = answer.selected;
    isCorrect = selected === q.correct;
    resultIcon.textContent = isCorrect ? '✓' : '✗';
    resultText.textContent = isCorrect ? '回答正确！' : '回答错误';
    resultExplanation.innerHTML = q.explanation + (isCorrect ? '' : `<br><br>你的选择：${q.options[selected]}`);
  } else if (q.type === 'calc') {
    const inputVal = document.getElementById('calcAnswer').value.trim();
    userAnswers[currentQuestion] = { type: 'calc', value: inputVal };
    isCorrect = q.acceptedAnswers.some(ans => inputVal === ans);
    resultIcon.textContent = isCorrect ? '✓' : '✗';
    resultText.textContent = isCorrect ? '回答正确！' : '回答错误';
    resultExplanation.innerHTML = q.explanation + (isCorrect ? '' : `<br><br>你的答案：${inputVal || '(空)'}`);
  }

  window.HeurisStage.emit('quiz-answer', {
    question: currentQuestion + 1,
    type: q.type,
    correct: isCorrect,
    score: isCorrect ? 1 : 0
  });
}

function showFinalResult() {
  const score = userAnswers.filter((ans, i) => {
    if (!ans) return false;
    const q = questions[i];
    if (q.type === 'choice') return ans.selected === q.correct;
    if (q.type === 'calc') return q.acceptedAnswers.some(a => a === ans.value);
    return false;
  }).length;

  questionArea.innerHTML = `
    <div class="final-result">
      <div class="final-label">你的得分</div>
      <div class="final-score">${score} / ${questions.length}</div>
      <div style="margin-top:20px;opacity:0.8">${score === questions.length ? '🏆 满分！太棒了！' : score >= 3 ? '👍 不错的成绩！' : '📚 继续加油！'}</div>
    </div>
  `;

  questionArea.classList.remove('hidden');
  resultArea.classList.add('hidden');
  prevBtn.classList.add('hidden');
  nextBtn.classList.add('hidden');
  submitQuiz.classList.add('hidden');

  window.HeurisStage.emit('quiz-complete', {
    total: questions.length,
    score: score,
    percentage: score / questions.length * 100
  });
}

prevBtn.addEventListener('click', () => {
  if (currentQuestion > 0) {
    currentQuestion--;
    renderQuestion();
  }
});

nextBtn.addEventListener('click', () => {
  if (currentQuestion < questions.length - 1) {
    currentQuestion++;
    renderQuestion();
  }
});

submitQuiz.addEventListener('click', showFinalResult);

// 如果当前是计算题，添加输入框回车事件
document.addEventListener('keypress', (e) => {
  if (e.key === 'Enter' && questions[currentQuestion].type === 'calc') {
    showResult();
  }
});

renderQuestion();
